func navSurfaceLabel(surface string) string {
	switch surface {
	case "dashboard":
		return "Dashboard"
	case "editor":
		return "Editor"
	case "library":
		return "Library"
	case "caelum":
		return "Caelum"
	case "share":
		return "Share"
	default:
		return "Verse"
	}
}

func navSurfacePath(surface string) string {
	switch surface {
	case "dashboard":
		return "/dashboard"
	case "editor":
		return "/editor"
	case "library":
		return "/library"
	case "caelum":
		return "/caelum"
	case "share":
		return "/share"
	default:
		return "/dashboard"
	}
}

func navActiveValue(surface string, path string) string {
	if navSurfacePath(surface) == path {
		return "true"
	}
	return "false"
}

